import {type BifurClient, ERROR_CODES, RpcError, WebSocketError} from '@sanity/bifur-client'
import {type User} from '@sanity/types'
import {dequal as isEqual} from 'dequal/lite'
import flatten from 'lodash-es/flatten.js'
import groupBy from 'lodash-es/groupBy.js'
import omit from 'lodash-es/omit.js'
import uniq from 'lodash-es/uniq.js'
import {nanoid} from 'nanoid'
import {
  BehaviorSubject,
  combineLatest,
  defer,
  EMPTY,
  from,
  merge,
  NEVER,
  type Observable,
  ReplaySubject,
  throwError,
  timer,
} from 'rxjs'
import {
  auditTime,
  catchError,
  distinctUntilChanged,
  filter,
  map,
  mergeMapTo,
  retry,
  scan,
  share,
  shareReplay,
  switchMap,
  switchMapTo,
  tap,
  withLatestFrom,
} from 'rxjs/operators'

import {documentIdEquals} from '../../util/draftUtils'
import {type ConnectionStatusStore} from '../connection-status/connection-status-store'
import {debugParams$} from '../debugParams/debugParams'
import {type UserStore} from '../user/userStore'
import {createBifurTransport} from './message-transports/bifurTransport'
import {
  type DisconnectEvent,
  type RollCallEvent,
  type StateEvent,
  type TransportEvent,
} from './message-transports/transport'
import {mock$} from './mock-events'
import {
  type DocumentPresence,
  type GlobalPresence,
  type PresenceLocation,
  type Session,
  type UserSessionPair,
} from './types'

/**
 * @hidden
 * @beta */
export interface PresenceStore {
  /**
   * @internal
   */
  documentPresence: (
    documentId: string,
    options?: {excludeVersions?: boolean},
  ) => Observable<DocumentPresence[]>

  /**
   * @internal
   */
  globalPresence$: Observable<GlobalPresence[]>

  /**
   * @internal
   */
  reportLocations: (locations: PresenceLocation[]) => Observable<void>

  /**
   * @internal
   */
  setLocation: (nextLocation: PresenceLocation[]) => void

  /**
   * @internal
   */
  debugPresenceParam$: Observable<string[]>

  /**
   * Debug helpers for exercising presence from a single browser. Fake sessions go through the
   * same code path as real ones (user lookup, document presence, form routing, overlay).
   * @internal
   */
  debug: PresenceDebugApi
}

/** @internal */
export interface PresenceDebugApi {
  /** The locations this session currently reports as its own, including any editor selection */
  ownLocation$: Observable<PresenceLocation[]>
  /** Shows `userId` as present at `locations`; calling it again for the same user moves them */
  fakePresence: (userId: string, locations: PresenceLocation[]) => void
  /** Removes the fake presence of `userId`, or of every faked user when omitted */
  removeFakePresence: (userId?: string) => void
}

const KEY = 'presence_session_id'
const generate = () => nanoid(16)

// We're keeping the session id in sessionStorage as it will survive page reloads.
// todo:
//  There's a potential issue with window.open(...) here as it inherits the top level session storage and thus will
//  re-use session ids:
//    > Opening a page in a new tab or window creates a new session with the value of the top-level browsing context,
//      which differs from how session cookies work.
//      More at https://developer.mozilla.org/en-US/docs/Web/API/Window/sessionStorage
//  This is _probably_ a quite marginal case and not going to be much of a issue in practice
function readStoredSessionId() {
  try {
    return window.sessionStorage.getItem(KEY)
  } catch {
    // We don't want to fail hard if session storage can't be accessed for some reason
  }
  return null
}

function storeSessionId(id: string) {
  try {
    window.sessionStorage.setItem(KEY, id)
  } catch {
    // We don't want to fail hard if session storage can't be accessed for some reason
  }
  return id
}

/** How long document presence keeps running after the last document stops using it. */
const DOCUMENT_PRESENCE_GRACE = 5_000

let sessionId: string | undefined

/**
 * The presence session id of this browsing context, created on first call rather than at import
 * so that importing `sanity` doesn't need random values (Cloudflare Workers forbid them there).
 *
 * @internal
 */
export function getSessionId(): string {
  sessionId ??= readStoredSessionId() || storeSessionId(generate())
  return sessionId
}

const isBifurError = (error: unknown): error is RpcError | WebSocketError =>
  error instanceof RpcError || error instanceof WebSocketError

const warnIfRejected = (error: RpcError | WebSocketError) => {
  // A closed socket is expected (the server dropped it, or the page is entering the back/forward
  // cache), so only a reply the server sent is worth a warning
  if (error instanceof RpcError)
    console.warn('Presence: the server returned an error: %s', error.message)
}

/** Presence requests are fire-and-forget: a failed one must not end presence */
const dropBifurError = (error: unknown) => {
  if (!isBifurError(error)) return throwError(() => error)
  warnIfRejected(error)
  return EMPTY
}

/** @internal */
export function createPresenceStore(context: {
  bifur: BifurClient
  connectionStatusStore: ConnectionStatusStore
  userStore: UserStore
}): PresenceStore {
  const {bifur, connectionStatusStore, userStore} = context
  const ownSessionId = getSessionId()

  const [transportEvents$, sendMessage] = createBifurTransport(bifur, ownSessionId)

  // A closed socket ends the presence subscription. In bifur-client v3 the same close also takes
  // the connection status through `error`, and the presence store subscribes again on reconnect.
  // Listening again after a delay as well is defensive, so presence doesn't depend on that. Not
  // after a rejected token, which the connection status store stops retrying, and not after a
  // subscription the server rejects, which would be rejected again: both wait for a reconnect.
  const presenceEvents$ = transportEvents$.pipe(
    retry({
      delay: (error: unknown, retryCount) =>
        error instanceof WebSocketError && error.code !== ERROR_CODES.UNAUTHORIZED
          ? timer(Math.min(1000 * 2 ** (retryCount - 1), 60_000))
          : throwError(() => error),
      resetOnSuccess: true,
    }),
    catchError(dropBifurError),
    share(),
  )

  const currentLocation$ = new BehaviorSubject<PresenceLocation[]>([])
  const locationChange$ = currentLocation$.pipe(distinctUntilChanged())

  // export
  const setLocation = (nextLocation: PresenceLocation[]) => {
    currentLocation$.next(nextLocation)
  }

  // export
  // A request that fails is dropped: the next announcement, at most REPORT_MIN_INTERVAL later,
  // sends the same state again.
  const reportLocations = (locations: PresenceLocation[]) =>
    sendMessage({type: 'state', locations: locations}).pipe(catchError(dropBifurError))

  const requestRollCall = () => sendMessage({type: 'rollCall'}).pipe(catchError(dropBifurError))

  const rollCallRequests$ = presenceEvents$.pipe(
    filter((event: TransportEvent): event is RollCallEvent => event.type === 'rollCall'),
    // do not respond to my own rollcall requests
    filter((event: RollCallEvent) => event.sessionId !== ownSessionId),
  )

  const REPORT_MIN_INTERVAL = 30000

  // Interval to report my own location at
  const reportLocationInterval$ = timer(0, REPORT_MIN_INTERVAL)

  const reportLocation$ = defer(() => merge(locationChange$, rollCallRequests$)).pipe(
    switchMap(() => reportLocationInterval$),
    withLatestFrom(currentLocation$),
    map(([, locations]) => locations),
    auditTime(200),
    switchMap((locations) => reportLocations(locations)),
    // oxlint-disable-next-line no-deprecated -- will fix in follow up PR
    mergeMapTo(EMPTY),
    share(),
  )

  // This represents my rollcall request to other clients
  // Note: We are requesting a rollcall whenever we (re)connect
  // oxlint-disable-next-line no-deprecated -- will fix in follow up PR
  const myRollCall$ = defer(() => requestRollCall()).pipe(mergeMapTo(EMPTY))

  const connectionChange$ = connectionStatusStore.connectionStatus$.pipe(
    map((status) => status.type),
    filter((statusType) => statusType === 'connected' || statusType === 'error'),
    distinctUntilChanged(),
  )

  // export
  const debugPresenceParam$ = debugParams$.pipe(
    map((args) => args.find((arg) => arg.startsWith('presence='))),
    map(
      (arg) =>
        arg
          ?.split('presence=')[1]
          .split(',')
          .map((r) => r.trim()) || [],
    ),
  )

  const useMock$ = debugPresenceParam$.pipe(
    filter((args) => args.includes('fake_others')),
    tap(() => {
      // oxlint-disable-next-line no-console
      console.log(
        'Faking other users present in the studio. They will hang out in the document with _type: "presence" and _id: "presence-debug"',
      )
    }),
    // oxlint-disable-next-line no-deprecated -- will fix in follow up PR
    switchMapTo(mock$),
  )

  const debugIntrospect$ = debugPresenceParam$.pipe(map((args) => args.includes('show_own')))

  // Fake sessions placed explicitly through the debug API (e.g. the test studio's field action).
  // Replayed so that sessions faked before anyone subscribed to presence are not lost.
  const debugEvents$ = new ReplaySubject<StateEvent | DisconnectEvent>()
  const fakedUserIds = new Set<string>()
  const fakeSessionId = (userId: string) => `fake-${userId}`
  const debug: PresenceDebugApi = {
    ownLocation$: currentLocation$.asObservable(),
    fakePresence: (userId, locations) => {
      fakedUserIds.add(userId)
      debugEvents$.next({
        type: 'state',
        userId,
        sessionId: fakeSessionId(userId),
        timestamp: new Date().toISOString(),
        locations,
      })
    },
    removeFakePresence: (userId) => {
      const userIds = userId === undefined ? Array.from(fakedUserIds) : [userId]
      for (const id of userIds) {
        fakedUserIds.delete(id)
        debugEvents$.next({
          type: 'disconnect',
          userId: id,
          sessionId: fakeSessionId(id),
          timestamp: new Date().toISOString(),
        })
      }
    },
  }

  const syncEvent$ = merge(myRollCall$, presenceEvents$).pipe(
    filter(
      (event: TransportEvent): event is StateEvent | DisconnectEvent =>
        event.type === 'state' || event.type === 'disconnect',
    ),
  )

  const stateEventToSession = (stateEvent: StateEvent): Session => {
    return {
      lastActiveAt: stateEvent.timestamp,
      locations: stateEvent.locations,
      sessionId: stateEvent.sessionId,
      userId: stateEvent.userId,
    }
  }

  const states$: Observable<{[sessionId: string]: Session}> = merge(
    syncEvent$,
    useMock$,
    debugEvents$,
  ).pipe(
    scan(
      (keyed, event: StateEvent | DisconnectEvent): {[sessionId: string]: Session} =>
        event.type === 'disconnect'
          ? omit(keyed, event.sessionId)
          : {...keyed, [event.sessionId]: stateEventToSession(event)},
      {},
    ),
  )

  const allSessions$: Observable<UserSessionPair[]> = connectionChange$.pipe(
    switchMap((status) => (status === 'connected' ? merge(states$, reportLocation$) : NEVER)),
    map((keyedSessions) => Object.values(keyedSessions)),
    switchMap((sessions) => {
      const userIds = uniq(sessions.map((sess) => sess.userId))
      return from(userStore.getUsers(userIds)).pipe(
        map((users) =>
          sessions
            .map((session) => ({
              user: users.find((res) => res.id === session.userId),
              session: session,
            }))
            // If we failed to find a user profile for a session, remove it
            .filter(userSessionPairHasUser),
        ),
      )
    }),
    shareReplay({refCount: true, bufferSize: 1}),
  )

  function userSessionPairHasUser(pair: Partial<UserSessionPair>): pair is UserSessionPair {
    return Boolean(pair.user && pair.session)
  }

  // export
  const globalPresence$: Observable<GlobalPresence[]> = allSessions$.pipe(
    map((sessions): {user: User; sessions: Session[]}[] => {
      const grouped = groupBy(
        sessions.map((s) => s.session),
        (e) => e.userId,
      )

      return Object.keys(grouped).map((userId): {user: User; sessions: Session[]} => ({
        user: sessions.find((s) => s.user.id === userId)?.user as User,
        sessions: grouped[userId],
      }))
    }),
    withLatestFrom(debugIntrospect$),
    map(([userAndSessions, debugIntrospect]) =>
      userAndSessions.filter(
        (userAndSession) =>
          debugIntrospect ||
          !userAndSession.sessions.some((sess) => sess.sessionId === ownSessionId),
      ),
    ),
    map((userAndSessions) =>
      userAndSessions.map((userAndSession) => ({
        user: userAndSession.user,
        status: 'online',
        lastActiveAt: userAndSession.sessions.sort((a, b) =>
          b.lastActiveAt.localeCompare(a.lastActiveAt),
        )[0]?.lastActiveAt,
        locations: flatten(
          (userAndSession.sessions || []).map((session) => session.locations || []),
        )
          .map((location) => ({
            type: location.type,
            documentId: location.documentId,
            path: location.path,
            lastActiveAt: location.lastActiveAt,
          }))
          .reduce((prev, curr) => prev.concat(curr), [] as PresenceLocation[]),
      })),
    ),
  )

  // Shared across documents, and released `DOCUMENT_PRESENCE_GRACE` after the last one stops
  // using it. Without the reset the first document subscriber pins `allSessions$` (the bifur
  // listener, the heartbeat watcher and the 30s location announcements) for the lifetime of the
  // page, so a workspace that has been switched away from keeps its socket open and keeps
  // announcing itself to the old dataset. The grace keeps it running while switching documents,
  // when the previous pane unmounts before the next one mounts, and while the login screen
  // replaces the studio after a session ends.
  const allDocumentsPresence$ = combineLatest([allSessions$, debugIntrospect$]).pipe(
    map(([userAndSessions, debugIntrospect]) =>
      userAndSessions
        .flatMap((userAndSession) =>
          (userAndSession.session.locations || []).map((location) => ({
            documentId: location.documentId,
            presence: {
              user: userAndSession.user,
              lastActiveAt: userAndSession.session.lastActiveAt,
              path: location.path || [],
              sessionId: userAndSession.session.sessionId,
              selection: location?.selection,
            },
          })),
        )
        .filter((item) => debugIntrospect || item.presence.sessionId !== ownSessionId),
    ),
    share({
      connector: () => new ReplaySubject(1),
      resetOnRefCountZero: () => timer(DOCUMENT_PRESENCE_GRACE),
    }),
  )

  /**
   * Returns document presence for the given documennt id
   * Presence are returned for all versions of the document
   */
  const documentPresence = (
    documentId: string,
    options?: {excludeVersions?: boolean},
  ): Observable<DocumentPresence[]> => {
    return allDocumentsPresence$.pipe(
      map((allPresence) =>
        allPresence
          .filter((item) =>
            options?.excludeVersions
              ? item.documentId === documentId
              : documentIdEquals(item.documentId, documentId),
          )
          .map((item) => ({
            ...item.presence,
            //documentId: getPublishedId(item.documentId),
            documentId: item.documentId,
          })),
      ),
      // Only emit if the presence has changed for this document id
      distinctUntilChanged((prev, curr) => isEqual(prev, curr)),
    )
  }

  return {
    setLocation,
    reportLocations,
    debugPresenceParam$,
    globalPresence$,
    documentPresence,
    debug,
  }
}
